-- Explicit --prepare-schema only. Definitions and address tuples from original sql/ resources.
DO $developer_pool$
DECLARE
    definitions text[] := ARRAY[
$ddl$CREATE TABLE IF NOT EXISTS TB_HR_DEV_PRC (
 DEV_ID VARCHAR(20) NOT NULL,
 APLY_BGN_YM CHAR(6) NOT NULL,
 APLY_END_YM CHAR(6),
 MON_UPRC NUMERIC(15),
 MON_PAY_AMT NUMERIC(15),
 REG_USER_ID VARCHAR(30) NOT NULL,
 REG_DTTM TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
 MOD_USER_ID VARCHAR(30),
 MOD_DTTM TIMESTAMPTZ,
 CONSTRAINT PK_TB_HR_DEV_PRC PRIMARY KEY (DEV_ID, APLY_BGN_YM)
)$ddl$,
$ddl$CREATE TABLE IF NOT EXISTS TB_HR_DEV_SKILL (
 DEV_ID VARCHAR(20) NOT NULL,
 SKILL_NM VARCHAR(50) NOT NULL,
 SORT_ORD NUMERIC(3) NOT NULL,
 REG_USER_ID VARCHAR(30) NOT NULL,
 REG_DTTM TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
 MOD_USER_ID VARCHAR(30),
 MOD_DTTM TIMESTAMPTZ,
 CONSTRAINT PK_TB_HR_DEV_SKILL PRIMARY KEY (DEV_ID, SKILL_NM)
)$ddl$,
$ddl$CREATE TABLE IF NOT EXISTS TB_HR_DEV_STAT (
 DEV_ID VARCHAR(20) NOT NULL,
 STAT_SN NUMERIC(5) NOT NULL,
 WORK_STAT_CD VARCHAR(10) NOT NULL,
 BGN_DT DATE NOT NULL,
 END_DT DATE,
 STAT_RSN VARCHAR(300),
 CLOSE_LEAVE_SN NUMERIC(5),
 ORGNL_LEAVE_END_DT DATE,
 REG_USER_ID VARCHAR(30) NOT NULL,
 REG_DTTM TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
 MOD_USER_ID VARCHAR(30),
 MOD_DTTM TIMESTAMPTZ,
 CONSTRAINT PK_TB_HR_DEV_STAT PRIMARY KEY (DEV_ID, STAT_SN)
)$ddl$,
$ddl$CREATE TABLE IF NOT EXISTS TB_HR_MON_PAY (
 PAY_YM CHAR(6) NOT NULL,
 DEV_ID VARCHAR(20) NOT NULL,
 PAY_AMT NUMERIC(15) NOT NULL,
 ALWNC_AMT NUMERIC(15) NOT NULL,
 INSR_CMPNY_AMT NUMERIC(15) NOT NULL,
 INSR_SELF_AMT NUMERIC(15),
 RETIRE_RSV_AMT NUMERIC(15) NOT NULL,
 INCM_TAX_AMT NUMERIC(15),
 WTHLD_TAX_AMT NUMERIC(15),
 REAL_PAY_AMT NUMERIC(15),
 VNDR_SPLY_AMT NUMERIC(15),
 EMP_TYPE_CD VARCHAR(10) NOT NULL,
 DRCT_CLS_CD VARCHAR(10) NOT NULL,
 UPLD_ID NUMERIC(12),
 REG_USER_ID VARCHAR(30) NOT NULL,
 REG_DTTM TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
 MOD_USER_ID VARCHAR(30),
 MOD_DTTM TIMESTAMPTZ,
 CONSTRAINT PK_TB_HR_MON_PAY PRIMARY KEY (PAY_YM, DEV_ID)
)$ddl$,
$ddl$CREATE TABLE IF NOT EXISTS TB_SY_ADM_HDONG (
 HDONG_CD VARCHAR(10) NOT NULL,
 AREA_CD VARCHAR(10) NOT NULL,
 HDONG_NM VARCHAR(30) NOT NULL,
 REG_USER_ID VARCHAR(30) NOT NULL,
 REG_DTTM TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
 MOD_USER_ID VARCHAR(30),
 MOD_DTTM TIMESTAMPTZ,
 CONSTRAINT PK_TB_SY_ADM_HDONG PRIMARY KEY (HDONG_CD, AREA_CD)
)$ddl$
    ];
    foreign_keys text[] := ARRAY[
        'ALTER TABLE TB_SY_ADM_HDONG ADD CONSTRAINT FK_TB_SY_ADM_HDONG_01 FOREIGN KEY (AREA_CD) REFERENCES TB_SY_ADM_AREA (AREA_CD)',
        'ALTER TABLE TB_HR_DEV_SKILL ADD CONSTRAINT FK_TB_HR_DEV_SKILL_01 FOREIGN KEY (DEV_ID) REFERENCES TB_HR_DEV (DEV_ID)',
        'ALTER TABLE TB_HR_DEV_PRC ADD CONSTRAINT FK_TB_HR_DEV_PRC_01 FOREIGN KEY (DEV_ID) REFERENCES TB_HR_DEV (DEV_ID)',
        'ALTER TABLE TB_HR_DEV_STAT ADD CONSTRAINT FK_TB_HR_DEV_STAT_01 FOREIGN KEY (DEV_ID) REFERENCES TB_HR_DEV (DEV_ID)',
        'ALTER TABLE TB_HR_MON_PAY ADD CONSTRAINT FK_TB_HR_MON_PAY_01 FOREIGN KEY (DEV_ID) REFERENCES TB_HR_DEV (DEV_ID)',
        'ALTER TABLE TB_HR_MON_PAY ADD CONSTRAINT FK_TB_HR_MON_PAY_02 FOREIGN KEY (UPLD_ID) REFERENCES TB_SY_UPLD (UPLD_ID)'
    ];
    indexes text[] := ARRAY[
        'CREATE INDEX IF NOT EXISTS IX_TB_SY_ADM_HDONG_01 ON TB_SY_ADM_HDONG (HDONG_NM)',
        'CREATE INDEX IF NOT EXISTS IX_TB_SY_ADM_HDONG_02 ON TB_SY_ADM_HDONG (AREA_CD)',
        'CREATE INDEX IF NOT EXISTS IX_TB_HR_MON_PAY_01 ON TB_HR_MON_PAY (DEV_ID)',
        'CREATE INDEX IF NOT EXISTS IX_TB_HR_MON_PAY_02 ON TB_HR_MON_PAY (UPLD_ID)'
    ];
    ddl text;
    line text;
    table_name text;
    relation regclass;
    parts text[];
    expected_type text;
    actual_type text;
    expected_default text;
    actual_default text;
    actual_required boolean;
    expected_constraint text;
    actual_constraint text;
    expected_columns text[];
    actual_columns text[];
    new_tables text[] := ARRAY[]::text[];
    differences text[] := ARRAY[]::text[];
BEGIN
    PERFORM pg_advisory_xact_lock(734901, 1);
    FOREACH ddl IN ARRAY definitions LOOP
        table_name := lower(substring(ddl FROM 'EXISTS ([A-Z_]+)'));
        relation := to_regclass(format('%I.%I', current_schema(), table_name));
        IF relation IS NULL THEN
            new_tables := array_append(new_tables, table_name);
            CONTINUE;
        END IF;
        IF NOT EXISTS (SELECT 1 FROM pg_class WHERE oid=relation AND relkind='r') THEN
            differences := array_append(differences, table_name || ': expected ordinary table');
            CONTINUE;
        END IF;
        EXECUTE format('LOCK TABLE %s IN ACCESS EXCLUSIVE MODE', relation);
        expected_columns := ARRAY[]::text[];
        FOREACH line IN ARRAY string_to_array(ddl, E'\n') LOOP
            parts := regexp_match(trim(line), '^([A-Z_][A-Z0-9_]*) ((?:VARCHAR|CHAR|NUMERIC)\([0-9,]+\)|TIMESTAMPTZ|DATE)(.*)$');
            IF parts IS NOT NULL THEN
                expected_columns := array_append(expected_columns, lower(parts[1]));
                expected_type := replace(replace(lower(parts[2]), 'varchar', 'character varying'), 'char(', 'character(');
                IF expected_type='timestamptz' THEN expected_type := 'timestamp with time zone'; END IF;
                IF expected_type ~ '^numeric\([0-9]+\)$' THEN expected_type := replace(expected_type, ')', ',0)'); END IF;
                expected_default := lower(rtrim(substring(parts[3] FROM 'DEFAULT (.+?)(?: NOT NULL|,$|$)'), ','));
                SELECT format_type(a.atttypid, a.atttypmod), a.attnotnull, lower(pg_get_expr(d.adbin,d.adrelid))
                  INTO actual_type, actual_required, actual_default
                  FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
                 WHERE a.attrelid=relation AND a.attname=lower(parts[1]) AND a.attnum>0 AND NOT a.attisdropped;
                actual_default := regexp_replace(actual_default, '::(bpchar|character varying|text|regclass)', '', 'g');
                IF actual_type IS DISTINCT FROM expected_type
                   OR actual_required IS DISTINCT FROM (position('NOT NULL' IN parts[3])>0)
                   OR actual_default IS DISTINCT FROM expected_default THEN
                    differences := array_append(differences, format('%s.%s expected type=%s required=%s default=%s actual type=%s required=%s default=%s',
                        table_name, lower(parts[1]), expected_type, position('NOT NULL' IN parts[3])>0,
                        expected_default, actual_type, actual_required, actual_default));
                END IF;
            END IF;
            parts := regexp_match(trim(line), '^CONSTRAINT ([A-Z_0-9]+) (.*?)(?:,)?$');
            IF parts IS NOT NULL THEN
                SELECT pg_get_constraintdef(oid) INTO actual_constraint FROM pg_constraint
                 WHERE conrelid=relation AND conname=lower(parts[1]) AND contype IN ('p','u','c') AND convalidated;
                actual_constraint := regexp_replace(lower(actual_constraint), '::(bpchar|text|character varying)', '', 'g');
                actual_constraint := replace(translate(regexp_replace(actual_constraint, '[[:space:]]', '', 'g'), '()[]', ''), '=anyarray', 'in');
                expected_constraint := translate(regexp_replace(lower(rtrim(parts[2], ',')), '[[:space:]]', '', 'g'), '()[]', '');
                IF actual_constraint IS DISTINCT FROM expected_constraint THEN
                    differences := array_append(differences, format('%s.%s expected=%s actual=%s', table_name, parts[1], expected_constraint, actual_constraint));
                END IF;
            END IF;
        END LOOP;
        SELECT array_agg(attname::text ORDER BY attnum) INTO actual_columns FROM pg_attribute
         WHERE attrelid=relation AND attnum>0 AND NOT attisdropped;
        IF actual_columns IS DISTINCT FROM expected_columns THEN
            differences := array_append(differences, format('%s.columns expected=%s actual=%s', table_name, expected_columns, actual_columns));
        END IF;
    END LOOP;
    FOREACH ddl IN ARRAY foreign_keys LOOP
        parts := regexp_match(ddl, '^ALTER TABLE ([A-Z_]+) ADD CONSTRAINT ([A-Z_0-9]+) (.+)$');
        relation := to_regclass(format('%I.%I', current_schema(), lower(parts[1])));
        IF relation IS NULL THEN CONTINUE; END IF;
        SELECT pg_get_constraintdef(oid) INTO actual_constraint FROM pg_constraint
         WHERE conrelid=relation AND conname=lower(parts[2]) AND contype='f' AND convalidated
           AND NOT condeferrable;
        expected_constraint := regexp_replace(lower(parts[3]), '[[:space:]]', '', 'g');
        actual_constraint := regexp_replace(lower(actual_constraint), '[[:space:]]', '', 'g');
        IF actual_constraint IS DISTINCT FROM expected_constraint THEN
            differences := array_append(differences, format('%s.%s expected=%s actual=%s', parts[1], parts[2], expected_constraint, actual_constraint));
        END IF;
    END LOOP;
    FOREACH ddl IN ARRAY indexes LOOP
        parts := regexp_match(ddl, 'EXISTS ([A-Z_0-9]+) ON ([A-Z_]+) \((.+)\)$');
        relation := to_regclass(format('%I.%I', current_schema(), lower(parts[2])));
        IF relation IS NULL THEN CONTINUE; END IF;
        IF NOT EXISTS (
            SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_am am ON am.oid=c.relam
             WHERE i.indrelid=relation AND c.relname=lower(parts[1]) AND i.indisvalid AND i.indisready
               AND NOT i.indisunique AND i.indpred IS NULL AND i.indexprs IS NULL AND am.amname='btree'
               AND i.indnatts=i.indnkeyatts
               AND (SELECT array_agg(pg_get_indexdef(i.indexrelid,n,true) ORDER BY n)
                      FROM generate_series(1,i.indnkeyatts) n)
                   = string_to_array(lower(replace(parts[3], ' ', '')), ',')
        ) THEN
            differences := array_append(differences, parts[1] || ': expected original btree index on ' || parts[3]);
        END IF;
    END LOOP;
    IF cardinality(differences)>0 THEN
        RAISE EXCEPTION USING MESSAGE=array_to_string(differences, E'\n'), ERRCODE='P0001';
    END IF;
    FOREACH ddl IN ARRAY definitions LOOP
        table_name := lower(substring(ddl FROM 'EXISTS ([A-Z_]+)'));
        IF table_name=ANY(new_tables) THEN EXECUTE ddl; END IF;
    END LOOP;
    FOREACH ddl IN ARRAY foreign_keys LOOP
        table_name := lower(substring(ddl FROM '^ALTER TABLE ([A-Z_]+)'));
        IF table_name=ANY(new_tables) THEN EXECUTE ddl; END IF;
    END LOOP;
    FOREACH ddl IN ARRAY indexes LOOP
        table_name := lower(substring(ddl FROM ' ON ([A-Z_]+)'));
        IF table_name=ANY(new_tables) THEN EXECUTE ddl; END IF;
    END LOOP;
    IF 'tb_hr_dev_prc'=ANY(new_tables) THEN
        COMMENT ON TABLE TB_HR_DEV_PRC IS '개발자단가급여이력';
        COMMENT ON COLUMN TB_HR_DEV_PRC.DEV_ID IS '개발자ID';
        COMMENT ON COLUMN TB_HR_DEV_PRC.APLY_BGN_YM IS '적용시작연월: 화면에서 고르지 않고 자동(2026-10-29): 등록 때 첫 줄은 입사월(입사일이 없으면 등록한 달), 수정에서 월 단가·월 급여가 바뀌면 저장한 달로 새 줄. 같은 달에 또 바꾸면 그 달 줄을 고침. 다른 칸(등급 등)만 바꾸면 줄을 만들지 않음';
        COMMENT ON COLUMN TB_HR_DEV_PRC.APLY_END_YM IS '적용종료연월: 새 줄이 생기면 앞 줄을 새 시작월의 전달로 닫음. 지금 줄은 NULL';
        COMMENT ON COLUMN TB_HR_DEV_PRC.MON_UPRC IS '월단가: 고객에게 받는 기본 단가(목록 표시용)';
        COMMENT ON COLUMN TB_HR_DEV_PRC.MON_PAY_AMT IS '월급여지급액: 회사가 주는 돈. 민감 항목';
        COMMENT ON COLUMN TB_HR_DEV_PRC.REG_DTTM IS '등록일시';
        COMMENT ON COLUMN TB_HR_DEV_PRC.MOD_DTTM IS '수정일시: 동시 수정 감지(낙관적 잠금)';
        COMMENT ON COLUMN TB_HR_DEV_PRC.REG_USER_ID IS 'TB_SY_USER.USER_ID 참조 의도 (FK 미선언)';
        COMMENT ON COLUMN TB_HR_DEV_PRC.MOD_USER_ID IS 'TB_SY_USER.USER_ID 참조 의도 (FK 미선언)';
    END IF;
    IF 'tb_hr_dev_skill'=ANY(new_tables) THEN
        COMMENT ON TABLE TB_HR_DEV_SKILL IS '개발자보유스킬';
        COMMENT ON COLUMN TB_HR_DEV_SKILL.DEV_ID IS '개발자ID';
        COMMENT ON COLUMN TB_HR_DEV_SKILL.SKILL_NM IS '스킬명: 쉼표로 입력한 값을 행으로 분리. 공통코드 SKILL 권장';
        COMMENT ON COLUMN TB_HR_DEV_SKILL.SORT_ORD IS '정렬순서';
        COMMENT ON COLUMN TB_HR_DEV_SKILL.REG_DTTM IS '등록일시';
        COMMENT ON COLUMN TB_HR_DEV_SKILL.MOD_DTTM IS '수정일시: 동시 수정 감지(낙관적 잠금)';
        COMMENT ON COLUMN TB_HR_DEV_SKILL.REG_USER_ID IS 'TB_SY_USER.USER_ID 참조 의도 (FK 미선언)';
        COMMENT ON COLUMN TB_HR_DEV_SKILL.MOD_USER_ID IS 'TB_SY_USER.USER_ID 참조 의도 (FK 미선언)';
    END IF;
    IF 'tb_hr_dev_stat'=ANY(new_tables) THEN
        COMMENT ON TABLE TB_HR_DEV_STAT IS '개발자근무상태이력';
        COMMENT ON COLUMN TB_HR_DEV_STAT.DEV_ID IS '개발자ID';
        COMMENT ON COLUMN TB_HR_DEV_STAT.STAT_SN IS '상태일련번호';
        COMMENT ON COLUMN TB_HR_DEV_STAT.BGN_DT IS '시작일자: 휴직=시작일, 재직=복귀일, 퇴사=퇴사일. RETIRE 줄의 BGN_DT가 퇴사일 원본(TB_HR_DEV.RETIRE_DT는 복사값, 2026-10-29)';
        COMMENT ON COLUMN TB_HR_DEV_STAT.END_DT IS '종료일자: NULL=복직일 미정. [휴직 종료] 시 실제 복직일로 변경';
        COMMENT ON COLUMN TB_HR_DEV_STAT.STAT_RSN IS '상태사유: 예: 육아휴직';
        COMMENT ON COLUMN TB_HR_DEV_STAT.CLOSE_LEAVE_SN IS '닫은휴직일련번호: WORK·RETIRE 줄만. 이 줄을 등록하면서 자동으로 닫은 휴직 줄의 STAT_SN(같은 DEV_ID). 닫은 휴직이 없으면 NULL. 아래 「휴직 닫기·되돌리기 규칙」';
        COMMENT ON COLUMN TB_HR_DEV_STAT.ORGNL_LEAVE_END_DT IS '원래휴직종료일자: WORK·RETIRE 줄만. 닫기 직전 그 휴직 줄의 END_DT(NULL이면 복직일 미정이었음). 이 줄을 취소할 때 되돌릴 값';
        COMMENT ON COLUMN TB_HR_DEV_STAT.REG_DTTM IS '등록일시';
        COMMENT ON COLUMN TB_HR_DEV_STAT.MOD_DTTM IS '수정일시: 동시 수정 감지(낙관적 잠금)';
        COMMENT ON COLUMN TB_HR_DEV_STAT.REG_USER_ID IS 'TB_SY_USER.USER_ID 참조 의도 (FK 미선언)';
        COMMENT ON COLUMN TB_HR_DEV_STAT.MOD_USER_ID IS 'TB_SY_USER.USER_ID 참조 의도 (FK 미선언)';
    END IF;
    IF 'tb_hr_mon_pay'=ANY(new_tables) THEN
        COMMENT ON TABLE TB_HR_MON_PAY IS '월별급여원가 - 부록 B.1 업로드';
        COMMENT ON COLUMN TB_HR_MON_PAY.PAY_YM IS '급여연월: 같은 연월 재업로드 시 덮어씀, 마감월 불가';
        COMMENT ON COLUMN TB_HR_MON_PAY.DEV_ID IS '개발자ID';
        COMMENT ON COLUMN TB_HR_MON_PAY.PAY_AMT IS '급여금액: 프리랜서는 지급액(원천세 차감 전)';
        COMMENT ON COLUMN TB_HR_MON_PAY.ALWNC_AMT IS '수당금액: 직위 수당(식-08). 엑셀 칸 아님: 업로드 때 공통코드(ALLOW_TEAM·ALLOW_GROUP)와 그 달 직위로 계산해 저장, 코드를 고치면 마감 안 된 달은 다시 계산(C4)';
        COMMENT ON COLUMN TB_HR_MON_PAY.INSR_CMPNY_AMT IS '4대보험회사부담금액: 업로드값 우선, 없으면 INS_RATE';
        COMMENT ON COLUMN TB_HR_MON_PAY.INSR_SELF_AMT IS '4대보험본인부담금액: 급여 업로드 값. 개인 원가·수익표(UI-03)에서는 참고 열(원가 아님). 실지급액(식-17)과 자금수지표 제경비(다음 달, 식-48)에 씀. 비어 있으면 0으로 봄(프리랜서·외주는 원래 없음, 2026-10-30 E4)';
        COMMENT ON COLUMN TB_HR_MON_PAY.RETIRE_RSV_AMT IS '퇴직금적립금액: 정규직만(식-09). 엑셀 칸 아님: 업로드 때 (급여 + 수당) × SEV_RATE로 계산해 저장, 코드를 고치면 마감 안 된 달은 다시 계산(C4)';
        COMMENT ON COLUMN TB_HR_MON_PAY.INCM_TAX_AMT IS '근로소득세금액: 급여 업로드 값. 실지급액(식-17)과 자금수지표 제경비(다음 달, 식-48)에 씀. 비어 있으면 0으로 봄(2026-10-30 E4)';
        COMMENT ON COLUMN TB_HR_MON_PAY.WTHLD_TAX_AMT IS '원천세금액: 3.3%(식-17). 급여 양식에 칸 없음, 업로드 때 시스템이 계산해 저장(2026-10-31)';
        COMMENT ON COLUMN TB_HR_MON_PAY.REAL_PAY_AMT IS '실지급금액: 식-17. 급여 양식에 칸 없음, 업로드 때 시스템이 계산해 저장(2026-10-31). 자금수지표 정규직·계약직 지출(2026-10-28 경비정산금액 EXPS_RFND_AMT 칸 삭제)';
        COMMENT ON COLUMN TB_HR_MON_PAY.VNDR_SPLY_AMT IS '외주공급가금액: 외주 원가';
        COMMENT ON COLUMN TB_HR_MON_PAY.EMP_TYPE_CD IS '직원구분코드: 업로드 때 TB_HR_DEV.EMP_TYPE_CD를 복사(엑셀 칸 아님, 그 달 기준 보존). 그 달 계산의 직원구분은 이 값: 개인 월 인건비(식-10)·배분 분모(식-13)·파트 월 비용(식-42)·자금수지 인건비 줄(식-48·49)·고정비 비율(식-64). 직원구분을 바꾸면 다음에 올리는 급여부터 새 값, 지난 달 줄은 그대로. 마감 전 같은 달을 다시 올리면 다시 복사(예: 10월까지 정규직, 11월부터 프리랜서 → 9·10월 FT, 11월 FL)(2026-10-31 C17)';
        COMMENT ON COLUMN TB_HR_MON_PAY.DRCT_CLS_CD IS '직간접구분코드: 업로드 때 TB_HR_DEV.DRCT_CLS_CD를 복사(엑셀 칸 아님, 그 달 기준 보존). 간접이면 판관비(식-15)';
        COMMENT ON COLUMN TB_HR_MON_PAY.UPLD_ID IS '업로드ID';
        COMMENT ON COLUMN TB_HR_MON_PAY.REG_DTTM IS '등록일시';
        COMMENT ON COLUMN TB_HR_MON_PAY.MOD_DTTM IS '수정일시: 동시 수정 감지(낙관적 잠금)';
        COMMENT ON COLUMN TB_HR_MON_PAY.REG_USER_ID IS 'TB_SY_USER.USER_ID 참조 의도 (FK 미선언)';
        COMMENT ON COLUMN TB_HR_MON_PAY.MOD_USER_ID IS 'TB_SY_USER.USER_ID 참조 의도 (FK 미선언)';
    END IF;
    IF 'tb_sy_adm_hdong'=ANY(new_tables) THEN
        COMMENT ON TABLE TB_SY_ADM_HDONG IS '행정동변환';
        COMMENT ON COLUMN TB_SY_ADM_HDONG.HDONG_CD IS '행정동코드: 행정동코드 10자리';
        COMMENT ON COLUMN TB_SY_ADM_HDONG.AREA_CD IS '행정구역코드: → TB_SY_ADM_AREA. 이 행정동이 걸친 법정동(읍·면·동 단계). 행정동 하나가 법정동 여러 개에 걸치면 여러 줄';
        COMMENT ON COLUMN TB_SY_ADM_HDONG.HDONG_NM IS '행정동명: 파일 표기 그대로(예: 자양제3동). 같은 시·군·구 안에서 이 이름으로 찾되 숫자 앞 「제」는 빼고 비교(자양3동 = 자양제3동, 02 SFR-021-04)';
        COMMENT ON COLUMN TB_SY_ADM_HDONG.REG_DTTM IS '등록일시';
        COMMENT ON COLUMN TB_SY_ADM_HDONG.MOD_DTTM IS '수정일시: 동시 수정 감지(낙관적 잠금)';
        COMMENT ON COLUMN TB_SY_ADM_HDONG.REG_USER_ID IS 'TB_SY_USER.USER_ID 참조 의도 (FK 미선언)';
        COMMENT ON COLUMN TB_SY_ADM_HDONG.MOD_USER_ID IS 'TB_SY_USER.USER_ID 참조 의도 (FK 미선언)';
    END IF;
    IF 'tb_hr_dev_stat'=ANY(new_tables) THEN
        COMMENT ON COLUMN TB_HR_DEV_STAT.WORK_STAT_CD IS 'LEAVE:휴직|RETIRE:퇴사|WORK:재직';
        COMMENT ON COLUMN TB_HR_DEV_STAT.END_DT IS '휴직 종료일. 복귀 저장 시 복귀일 전날로 갱신하며 NULL은 미정이다.';
        COMMENT ON COLUMN TB_HR_DEV_STAT.CLOSE_LEAVE_SN IS '같은 DEV_ID의 TB_HR_DEV_STAT.STAT_SN 참조 의도 (FK 미선언); 재직·퇴사 저장 때 닫은 휴직 줄을 보존';
    END IF;
    IF 'tb_hr_dev_prc'=ANY(new_tables) THEN
        COMMENT ON COLUMN TB_HR_DEV_PRC.APLY_BGN_YM IS '개발자 등록·금액 수정 저장 시 Asia/Seoul 저장월로 결정';
        COMMENT ON COLUMN TB_HR_DEV_PRC.APLY_END_YM IS '새 적용월 저장 시 애플리케이션이 직전 기간의 종료월을 갱신하고 다음 기간은 보존';
    END IF;
END;
